//! Chinese lunisolar calendar conversion.
//!
//! The table is generated by tools/unicode/format/generate_chinese.py from
//! PyICU for complete Chinese years covering roughly 1850-2150. Each record
//! stores the year's first day, cycle era, year-in-cycle, leap month, and a
//! month-length bitmask.

const std = @import("std");
const calendar = @import("calendar.zig");

const blob = @embedFile("chinese_data.bin");

const header_len = 12;
const year_count = readU16(8);
const record_offset = header_len;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJK1") or
        blob[4] != 1)
    {
        @compileError("invalid Chinese calendar data");
    }
    if (record_offset + @as(usize, year_count) * 12 != blob.len) {
        @compileError("invalid Chinese calendar data lengths");
    }
}

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readI32(offset: usize) i32 {
    return std.mem.readInt(i32, blob[offset..][0..4], .little);
}

const Record = struct {
    start: i32,
    era: u16,
    year: u8,
    month_count: u8,
    leap_month: u8,
    mask: u16,
};

fn recordAt(index: usize) Record {
    const base = record_offset + index * 12;
    return .{
        .start = readI32(base),
        .era = readU16(base + 4),
        .year = blob[base + 6],
        .month_count = blob[base + 7],
        .leap_month = blob[base + 8],
        .mask = readU16(base + 10),
    };
}

/// Convert days since 1970-01-01 to Chinese calendar fields.
pub fn fromDays(days: i64) ?calendar.Date {
    var low: usize = 0;
    var high: usize = year_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        if (recordAt(middle).start <= days) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low == 0) return null;
    const record = recordAt(low - 1);
    var remaining = days - record.start;
    var index: u8 = 0;
    while (index < record.month_count) : (index += 1) {
        const length: i64 = if (record.mask & (@as(u16, 1) << @intCast(index)) != 0)
            30
        else
            29;
        if (remaining < length) break;
        remaining -= length;
    }
    var month: u8 = undefined;
    var leap = false;
    if (record.leap_month == 0 or index < record.leap_month) {
        month = index + 1;
    } else if (index == record.leap_month) {
        month = record.leap_month;
        leap = true;
    } else {
        month = index;
    }
    return .{
        .era = record.era,
        .year = record.year,
        .month = month,
        .day = @intCast(remaining + 1),
        .leap_month = leap,
        .leap_year = record.leap_month != 0,
    };
}

test "Chinese calendar conversion" {
    const testing = @import("std").testing;
    // 2024-01-15 -> cycle 78, year 40, month 12, day 5.
    const january = calendar.daysFromGregorian(2024, 1, 15);
    const first = fromDays(january).?;
    try testing.expectEqual(@as(u16, 78), first.era);
    try testing.expectEqual(@as(i32, 40), first.year);
    try testing.expectEqual(@as(u8, 12), first.month);
    try testing.expectEqual(@as(u8, 5), first.day);
    try testing.expect(!first.leap_month);
    // 2024-02-10 is Chinese New Year (month 1, day 1).
    const new_year = fromDays(calendar.daysFromGregorian(2024, 2, 10)).?;
    try testing.expectEqual(@as(i32, 41), new_year.year);
    try testing.expectEqual(@as(u8, 1), new_year.month);
    try testing.expectEqual(@as(u8, 1), new_year.day);
    // 2023-03-22 is the leap second month.
    const leap = fromDays(calendar.daysFromGregorian(2023, 3, 22)).?;
    try testing.expectEqual(@as(i32, 40), leap.year);
    try testing.expectEqual(@as(u8, 2), leap.month);
    try testing.expectEqual(@as(u8, 1), leap.day);
    try testing.expect(leap.leap_month);
}
